          "expected_facts": [
            "患者的过敏事件发生在2019年夏天。",
            "自那以后患者严格避免接触任何含青霉素的药物。"
          ],
          "required_groups": [
            ["2019年", "2019年夏天"],
            ["避免接触", "严格避免", "不再使用"]
          ]
        }
      ]
